{
 "id": "model-rail-loop",
 "name": "Model Rail Loop",
 "idea": "A small oval of double rails and sleepers around a flock grass infield, where a short red train runs one lap every 16 seconds past two platforms under a soft lamp glow, while slow window light drifts over the board and a signal turns from green to red as it passes.",
 "use": [
  "progress",
  "stepper",
  "loading",
  "empty-state"
 ],
 "frag": "precision highp float;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec3 u_c0;
uniform vec3 u_c1;
uniform vec3 u_c2;
uniform vec3 u_c3;
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float n(vec2 p){vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(h(i),h(i+vec2(1.0,0.0)),f.x),mix(h(i+vec2(0.0,1.0)),h(i+vec2(1.0,1.0)),f.x),f.y);}
float bx(vec2 p,vec2 b){vec2 d=abs(p)-b;return length(max(d,0.0))+min(max(d.x,d.y),0.0);}
vec2 tp(float s,float Lh,float r){
if(s<2.0*Lh)return vec2(s-Lh,-r);
s-=2.0*Lh;
if(s<3.14159*r){float a=s/r-1.5708;return vec2(Lh+r*cos(a),r*sin(a));}
s-=3.14159*r;
if(s<2.0*Lh)return vec2(Lh-s,r);
s-=2.0*Lh;
float a=s/r+1.5708;return vec2(-Lh+r*cos(a),r*sin(a));}
void main(){
vec2 p=(gl_FragCoord.xy-0.5*u_resolution)/u_resolution.y;
float px=1.5/u_resolution.y;
float a=u_resolution.x/u_resolution.y;
float w=step(1.0,a);
vec2 C=mix(vec2(0.0,0.12),vec2(0.3,0.0),w);
float Lh=mix(0.2,0.28,w);
float r=mix(0.15,0.2,w);
vec2 q=p-C;
q=mix(vec2(q.y,-q.x),q,w);
vec2 dd=vec2(max(abs(q.x)-Lh,0.0),q.y);
float sd=length(dd)-r;
float P=4.0*Lh+3.14159*r;
float s=0.0;
if(q.x>Lh){s=2.0*Lh+r*(atan(q.y,q.x-Lh)+1.5708);}
else if(q.x<-Lh){s=4.0*Lh+3.14159*r+r*mod(atan(q.y,q.x+Lh)-1.5708,6.2832);}
else if(q.y<0.0){s=q.x+Lh;}
else{s=2.0*Lh+3.14159*r+Lh-q.x;}
vec3 col=u_c0;
float inner=1.0-smoothstep(-0.03-px,-0.03,sd);
float fl=n(gl_FragCoord.xy*0.35)*0.6+h(gl_FragCoord.xy)*0.4;
col=mix(col,u_c3,inner*(0.1+0.06*fl));
float sp0=mod(u_time*P/16.0,P);
float Lt=0.13;
vec2 tc=tp(mod(sp0+Lt*0.5,P),Lh,r);
float gd=length(q-tc);
col=mix(col,u_c2,0.18*exp(-gd*gd/0.02));
col=mix(col,u_c1,0.05*(1.0-smoothstep(0.024,0.024+px,abs(sd))));
float sp=0.02;
float sl=abs(fract(s/sp)-0.5)*sp;
float slp=(1.0-smoothstep(0.0028,0.0028+px,sl))*(1.0-smoothstep(0.019,0.019+px,abs(sd)));
col=mix(col,u_c1,slp*0.35);
float rail=1.0-smoothstep(0.0011,0.0011+px,abs(abs(sd)-0.011));
col=mix(col,u_c1,rail*0.85);
float ds=mod(s-sp0,P);
float tb=smoothstep(0.0,px,ds)*(1.0-smoothstep(Lt-px,Lt,ds));
float cm=1.0-smoothstep(0.039-px,0.039,fract(ds/0.0433)*0.0433);
float wd=1.0-smoothstep(0.009,0.009+px,abs(sd));
col=mix(col,u_c2,tb*cm*wd);
float st=min(bx(q-vec2(0.0,-r-0.045),vec2(0.06,0.01)),bx(q-vec2(0.0,r+0.045),vec2(0.06,0.01)));
col=mix(col,u_c1,(1.0-smoothstep(0.0,px,st))*0.7);
float blk=mod(sp0+Lt-Lh+0.25,P);
float sig=smoothstep(0.0,0.04,blk)*(1.0-smoothstep(0.25+Lt,0.29+Lt,blk));
float sg=1.0-smoothstep(0.011,0.011+px,length(q-vec2(0.085,-r-0.045)));
col=mix(col,mix(u_c3,u_c2,sig),sg);
float cl=n(p*1.6+vec2(u_time*0.05,u_time*0.02));
cl=smoothstep(0.3,0.8,cl);
col*=1.0-0.08*cl;
col+=(h(gl_FragCoord.xy+3.7)-0.5)*0.03;
gl_FragColor=vec4(col,1.0);
}",
 "colors": [
  "#ece7d9",
  "#22231f",
  "#c43a2a",
  "#3f6b4a"
 ],
