{
 "id": "ma-pebble-group-settle",
 "name": "Pebble Group Settle",
 "idea": "On a pale paper field, a small indigo group of three soft stones rests on a short hairline in the lower right. Over a 12 second breath they lift, draw together and settle down onto the line, while a broad soft light slides across the paper and one tiny charcoal mark sits far away in the upper left.",
 "use": [
  "empty-state",
  "success",
  "onboarding-slide",
  "paywall-plan"
 ],
 "frag": "precision highp float;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec3 u_c0;
uniform vec3 u_c1;
uniform vec3 u_c2;
uniform vec3 u_c3;
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float sm(float a,float b,float k){float e=clamp(0.5+0.5*(b-a)/k,0.0,1.0);return mix(b,a,e)-k*e*(1.0-e);}
float pb(vec2 p,vec2 c,float r){vec2 q=p-c;q.y*=1.35;return length(q)-r;}
void main(){
 vec2 R=u_resolution;
 vec2 f=gl_FragCoord.xy;
 vec2 uv=f/R;
 vec2 p=(f-0.5*R)/R.y;
 float a=R.x/R.y;
 float px=1.5/R.y;
 float t=u_time;
 float s=smoothstep(0.15,0.85,0.5+0.5*sin(t*0.5236));
 float gp=0.045-0.035*s;
 float dy=0.035*(1.0-s);
 vec2 g=vec2((0.68-0.5)*a,-0.12+dy);
 float d=pb(p,g,0.034);
 d=sm(d,pb(p,vec2(g.x+0.052+gp,-0.130+dy*1.4),0.018),0.01);
 d=sm(d,pb(p,vec2(g.x-0.046-gp*0.7,-0.136+dy*0.7),0.012),0.01);
 vec3 col=u_c0*(0.95+0.05*uv.y);
 float L=0.5+0.5*sin(dot(p,vec2(0.6,0.8))*2.2-t*0.5236);
 col*=0.93+0.07*L;
 col=mix(col,u_c3,0.06*L);
 float ly=-0.147;
 float sh=exp(-pow(length((p-vec2(g.x,ly))*vec2(7.0,70.0)),2.0));
 col=mix(col,u_c3,sh*(0.15+0.3*s));
 float ln=(1.0-smoothstep(0.4,1.4,abs(f.y-R.y*(0.5+ly))))*smoothstep(0.44,0.52,uv.x)*(1.0-smoothstep(0.9,0.97,uv.x));
 col=mix(col,u_c3,ln*0.6);
 float m=1.0-smoothstep(-px,px,d);
 float lt=clamp((p.y-g.y)*25.0+0.5,0.0,1.0);
 vec3 pc=mix(mix(u_c2,u_c1,0.35),mix(u_c2,u_c0,0.15),lt);
 col=mix(col,pc,m);
 vec2 b=vec2((0.22-0.5)*a,0.27+0.012*sin(t*0.4488));
 float d2=pb(p,b,0.009);
 col=mix(col,u_c1,(1.0-smoothstep(-px,px,d2))*0.8);
 col+=(h(f)-0.5)*0.025;
 gl_FragColor=vec4(col,1.0);
}",
 "colors": [
  "#f5f2eb",
  "#1e1c1a",
  "#2f4858",
  "#9a8f80"
 ],
 "reduced": {
  "kind": "fade",
  "at": 3,
  "ms": 400,
  "note": "The three stones sit close together on the hairline in the lower right, and the tiny mark rests far off in the upper left."
 },
 "cardIds": [
  "everything-in-a-bento-grid"
 ],
 "lensIds": [
  "japanese-ma"
 ],
 "culturalNotes": "Follows ma, the Japanese idea of meaningful empty space, and credits the Japanese people, designers and makers who carry it. It borrows the lens proportion and grouping: one small mass balanced off center against a wide empty field, never mirrored, with parts that sit close inside a group and groups that sit far apart. The single main stone with two small sides also echoes the balance of one main portion against small sides from the bento box tradition of Japanese bento makers. The motion verb is settle. No script, symbol or artwork is drawn."
}
