{
 "id": "talli-halftone-stepper",
 "name": "Talli Halftone Stepper",
 "idea": "A vertical trim of five rounded segments on the left edge, each a halftone dot screen of chevron strands that shifts in strict even steps, fills with two alternating colors one segment at a time under a soft gliding glow.",
 "use": [
  "stepper",
  "progress",
  "sidebar",
  "onboarding-slide"
 ],
 "frag": "precision highp float;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec3 u_c0;
uniform vec3 u_c1;
uniform vec3 u_c2;
uniform vec3 u_c3;
float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
void main(){
vec2 r=u_resolution;
vec2 p=(gl_FragCoord.xy-0.5*r)/r.y;
float aa=1.5/r.y;
float a=r.x/r.y;
float lw=0.5/r.y;
float h=0.03;
float xc=-0.5*a+0.07;
float sl=0.168;
vec3 col=u_c0*(0.92+0.1*(p.x/a+0.5));
float yy=clamp(p.y,-0.4199,0.4199);
float id=floor((yy+0.42)/sl);
float ys=-0.42+(id+0.5)*sl;
vec2 v=vec2(p.x-xc,p.y-ys);
vec2 b=vec2(h,0.5*sl-0.008);
float rr=h*0.8;
vec2 e=abs(v)-b+rr;
float d=length(max(e,0.0))+min(max(e.x,e.y),0.0)-rr;
float m=1.0-smoothstep(-aa,aa,d);
float ti=4.0-id;
float ph=mod(u_time,18.0);
float fo=1.0-smoothstep(16.5,18.0,ph);
float fl=smoothstep(3.0*ti+2.0,3.0*ti+3.0,ph)*fo;
vec2 q=v/h;
float gs=0.25;
vec2 cc=(floor(q/gs)+0.5)*gs;
float stp=floor(u_time/2.0)+smoothstep(0.0,0.7,fract(u_time/2.0));
float bd=(cc.y+abs(cc.x))*0.5-stp*gs*0.5;
float I=1.0-abs(fract(bd)-0.5)*2.0;
float rad=gs*0.5*(0.25+0.7*I);
float dm=1.0-smoothstep(rad-aa/h,rad,length(q-cc));
vec3 dc=mod(floor(bd),2.0)<1.0?u_c2:u_c1;
vec3 dim=mix(u_c0,u_c3,0.35);
vec3 sc=mix(u_c0*0.62,mix(dim,dc,fl),dm*mix(0.6,1.0,fl));
col=mix(col,sc,m);
float ol=1.0-smoothstep(0.0,aa,abs(d-0.004)-lw);
col=mix(col,u_c3,ol*mix(0.35,0.85,fl));
float rx=xc+h+0.016;
float rl=(1.0-smoothstep(0.0,aa,abs(p.x-rx)-lw))*(1.0-smoothstep(0.42,0.425,abs(p.y)));
col=mix(col,u_c3,rl*0.45);
float gy=0.42-sl*(0.5+clamp((ph-2.5)/3.0,0.0,4.0));
vec2 g=p-vec2(xc,gy);
col+=u_c2*exp(-dot(g,g)*150.0)*0.14*fo*smoothstep(1.0,2.5,ph);
col+=(hash(gl_FragCoord.xy)-0.5)*0.03;
gl_FragColor=vec4(col,1.0);
}",
 "colors": [
  "#1f2340",
  "#f4efe6",
  "#2f7a4f",
  "#b9bcc2"
 ],
 "reduced": {
  "kind": "fade",
  "at": 15.5,
  "ms": 300,
  "note": "All five trim segments on the left edge show filled with dot-screen chevrons and fade in once."
 },
 "cardIds": [
  "emirati-talli-braiding"
 ],
 "lensIds": [
  "talli"
 ],
 "culturalNotes": "Follows Al Talli, the narrow braided trim of the United Arab Emirates, made mostly by Emirati women. It is recorded by UNESCO as Al Talli, traditional embroidery skills in the United Arab Emirates. Credit goes to the Emirati women who braid Talli and to the community that keeps the craft alive. The shader borrows the strict even step of the repeat and the two colors that alternate in a fixed order. The trim stays a narrow strip on one edge beside a wide plain field. Each segment has closed rounded ends, and silver hairlines divide the trim from the page. The crossing strands become an abstract dot screen. It copies no real piece and gives the shapes no meaning. A Talli braider or Emirati heritage practitioner should review it."
}
```

