{
 "id": "bisht-zari-edge-sheen",
 "name": "Zari Edge Sheen",
 "idea": "A near-black twill field with one narrow band of slanted gold stitches and a fine silver thread beside it near the leading edge, while a soft glint of light and its warm halo slide slowly down the band about every 11 seconds over a gently drifting weave.",
 "use": [
  "hero",
  "paywall-plan",
  "sidebar",
  "success"
 ],
 "frag": "precision highp float;
uniform vec2 u_resolution;   // canvas size in pixels
uniform float u_time;        // seconds since start
uniform vec3 u_c0;           // surface, fills most of the frame
uniform vec3 u_c1;           // ink
uniform vec3 u_c2;           // accent
uniform vec3 u_c3;           // support
float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
void main(){
vec2 p=(gl_FragCoord.xy-0.5*u_resolution)/u_resolution.y;
vec2 fc=gl_FragCoord.xy;
float aa=1.5/u_resolution.y;
float asp=u_resolution.x/u_resolution.y;
float bw=0.011;
float dx=p.x-(-0.5*asp+0.07);
float inB=1.0-smoothstep(bw-aa,bw+aa,abs(dx));
float u=(p.y+dx*0.8)/0.012;
float st=1.0-smoothstep(0.26,0.26+aa/0.012,abs(fract(u)-0.5));
float xr=dx/bw;
float rd=sqrt(max(0.0,1.0-xr*xr));
float sy=0.6-mod(u_time*0.09,1.0)*1.4;
float dy=p.y-sy;
float sh=exp(-dy*dy*16.0);
float sw=exp(-dy*dy*5.0);
vec3 th=mix(u_c2*0.35,u_c2*(0.7+0.4*rd),st);
th=mix(th,u_c1,sh*st*rd*0.6);
float tw=smoothstep(0.25,0.75,abs(fract((fc.x+fc.y+u_time*3.0)/6.0)-0.5)*2.0);
float lift=0.25*sin(u_time*0.52);
vec3 col=u_c0*(0.9+0.2*smoothstep(-0.7,0.7,p.y+lift));
col+=u_c1*0.03*(tw-0.5);
col+=u_c2*(0.04+0.12*sw)*exp(-max(dx,0.0)*6.0);
float sl=1.0-smoothstep(0.0012,0.0012+aa,abs(dx-bw-0.009));
col=mix(col,u_c3*(0.55+0.45*sh),sl*0.8);
col=mix(col,th,inB);
col+=(hash(fc)-0.5)*0.02;
gl_FragColor=vec4(col,1.0);
}",
 "colors": [
  "#14110f",
  "#efe6d6",
  "#c9a24a",
  "#b8b2a7"
 ],
 "reduced": {
  "kind": "static",
  "at": 4,
  "note": "The dark twill field with the gold stitch band at the edge, its soft glint and warm halo resting near the middle."
 },
 "cardIds": [
  "bisht-zari-edging"
 ],
 "lensIds": [],
 "culturalNotes": "Follows the zari edging of the bisht, the Gulf man's cloak worn over the thobe for weddings, Eid and formal occasions, with gold or silver thread hand-stitched along the front opening and sleeves. It credits the Gulf bisht tailors and embroiderers, with Al-Ahsa in eastern Saudi Arabia long known for the craft. The shader borrows the logic that ornament lives only on the opening edge, the narrow band against a wide plain field, and the ratio of dark wool to metal thread. The slanted stitch is generic and copies no workshop's pattern. The band sits on the left for Latin layouts; mirror the x coordinate to put it on the right for Arabic layouts."
}
