{
 "id": "mabkhara-smoke-thread",
 "name": "Mabkhara Smoke Thread",
 "idea": "One ember glows low on the right inside a fine flared bowl line, and a single thin smoke thread rises and sways slowly above it. A row of brass studs runs along the top edge with a slow glint passing across.",
 "use": [
  "hero",
  "success",
  "empty-state",
  "onboarding-slide"
 ],
 "frag": "precision highp float;
uniform vec2 u_resolution;   // canvas size in pixels
uniform float u_time;        // seconds since start
uniform vec3 u_c0;           // surface, fills most of the frame
uniform vec3 u_c1;           // ink
uniform vec3 u_c2;           // accent
uniform vec3 u_c3;           // support
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float n(vec2 p){vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(h(i),h(i+vec2(1.0,0.0)),f.x),mix(h(i+vec2(0.0,1.0)),h(i+vec2(1.0,1.0)),f.x),f.y);}
float fb(vec2 p){float s=0.0;float a=0.5;for(int i=0;i<3;i++){s+=a*n(p);p=p*2.03+vec2(1.7,9.2);a*=0.5;}return s;}
void main(){
vec2 p=(gl_FragCoord.xy-0.5*u_resolution)/u_resolution.y;
float px=1.5/u_resolution.y;
float ar=u_resolution.x/u_resolution.y;
float t=u_time;
vec3 col=u_c0*(0.88+0.2*(p.y+0.5));
vec2 e=vec2(0.22*ar,-0.3);
float y=p.y-e.y;
float k=clamp(y/0.72,0.0,1.0);
float wn=n(vec2(y*3.0-t*0.4,t*0.15))-0.5;
float sx=e.x+0.05*k*sin(t*0.6)+(0.008+0.05*k)*sin(y*8.0-t*1.1)+0.03*k*k*sin(y*15.0-t*1.6+1.7)+0.06*k*wn;
float w=0.0025+0.016*k*k;
float dl=p.x-sx;
float fd=smoothstep(0.0,0.06,y)*(1.0-smoothstep(0.35,0.75,y));
float pu=0.55+0.7*n(vec2(dl*14.0,y*5.0-t*0.9));
float sm=exp(-dl*dl/(w*w))*fd*(0.85-0.4*k)*pu;
float hz=fb(vec2(dl*5.0,y*3.0-t*0.5))*exp(-dl*dl/0.012)*fd*k;
col=mix(col,u_c1,clamp(sm*0.5+hz*0.16,0.0,1.0));
float br=0.78+0.22*sin(t*0.8);
vec2 q=(p-e)*vec2(1.0,1.5);
float lq=length(q);
col+=u_c2*(exp(-lq*11.0)*0.55+exp(-lq*3.0)*0.12)*br;
col+=u_c2*0.05*(br-0.78)*exp(-length(p-e)*1.2);
col=mix(col,mix(u_c2,u_c1,0.3),(1.0-smoothstep(0.011,0.011+px,lq))*0.9*br);
float dx=p.x-e.x;
float bw=e.y-0.035+2.2*dx*dx;
float bl=(1.0-smoothstep(0.0012,0.0012+px,abs(p.y-bw)))*(1.0-smoothstep(0.07,0.085,abs(dx)));
col=mix(col,u_c3,bl*0.55);
float st=0.034;
float fx=(fract(p.x/st)-0.5)*st;
float sd=length(vec2(fx,p.y-0.455));
float gx=-0.5*ar-0.3+mod(t*0.2,ar+0.6);
float gl=exp(-abs(p.x-gx)*7.0);
col=mix(col,u_c3*(0.55+0.8*gl),1.0-smoothstep(0.0042,0.0042+px,sd));
col=mix(col,u_c3*(0.8+0.6*gl),(1.0-smoothstep(0.0006,0.0006+px,abs(p.y-0.433)))*0.3);
col+=(h(floor(gl_FragCoord.xy))-0.5)*0.03;
col*=1.0-0.3*dot(p*vec2(0.5,1.0),p*vec2(0.5,1.0));
gl_FragColor=vec4(col,1.0);
}",
